export const MODULES = {
  DASHBOARD: 'DASHBOARD',
  CHILDREN: 'CHILDREN',
  THERAPY: 'THERAPY',
  ASSESSMENTS: 'ASSESSMENTS',
  NUTRITION: 'NUTRITION',
  OUTREACH: 'OUTREACH',
  SUCCESS_STORIES: 'SUCCESS_STORIES',
  REPORTS: 'REPORTS',
  USER_MANAGEMENT: 'USER_MANAGEMENT',
  DEVICES: 'DEVICES',
  TRAINING: 'TRAINING',
  MEETINGS: 'MEETINGS',
  COMMUNITY: 'COMMUNITY',
};

export const ACTIONS = {
  VIEW: 'VIEW',
  CREATE: 'CREATE',
  EDIT: 'EDIT',
  DELETE: 'DELETE',
  GENERATE_REPORT: 'GENERATE_REPORT',
  MANAGE_USERS: 'MANAGE_USERS',
};

const isAdminLikeUser = (user) => {
  if (!user) return false;
  const role = (user.role || '').toLowerCase();
  const groups = Array.isArray(user.groups) ? user.groups : [];
  return Boolean(
    user.is_superuser ||
    role === 'administrator' ||
    role === 'admin' ||
    groups.some((group) => ['Administrator', 'Admin'].includes(group))
  );
};

export const hasPermission = (user, module, action) => {
  if (!user) return false;
  if (isAdminLikeUser(user)) return true;
  const permissions = user.permissions || [];
  return permissions.some((p) => p.module === module && p.action === action);
};

export const canViewModule = (user, module) => hasPermission(user, module, ACTIONS.VIEW);
export const canCreate = (user, module) => hasPermission(user, module, ACTIONS.CREATE);
export const canEdit = (user, module) => hasPermission(user, module, ACTIONS.EDIT);
export const canDelete = (user, module) => hasPermission(user, module, ACTIONS.DELETE);
export const canGenerateReports = (user) => hasPermission(user, MODULES.REPORTS, ACTIONS.GENERATE_REPORT);
export const canManageUsers = (user) => hasPermission(user, MODULES.USER_MANAGEMENT, ACTIONS.MANAGE_USERS);

export const getAccessibleModules = (user) => {
  if (!user) return [];
  if (isAdminLikeUser(user)) return Object.values(MODULES);
  const permissions = user.permissions || [];
  return Array.from(new Set(permissions.map((p) => p.module)));
};

export const canAccessRoute = (user, route) => {
  if (!user) return false;
  if (isAdminLikeUser(user)) return true;

  const viewMap = {
    '/dashboard': MODULES.DASHBOARD,
    '/children': MODULES.CHILDREN,
    '/outreach': MODULES.OUTREACH,
    '/assessments': MODULES.ASSESSMENTS,
    '/therapy': MODULES.THERAPY,
    '/devices': MODULES.DEVICES,
    '/training': MODULES.TRAINING,
    '/nutrition': MODULES.NUTRITION,
    '/community': MODULES.COMMUNITY,
    '/meetings': MODULES.MEETINGS,
    '/success-stories': MODULES.SUCCESS_STORIES,
    '/reports': MODULES.REPORTS,
    '/users': MODULES.USER_MANAGEMENT,
    '/profile': MODULES.DASHBOARD,
  };

  const module = viewMap[route];
  return module ? canViewModule(user, module) : true;
};
